// Share the usable form specimens across component and composition pages.
const forms = SHOWCASE_PAGES.find((page) => page.slug === "examples-form-controls");
forms.html = forms.html.replace(/<span class="uix-taginput"[\s\S]*?<\/span>\s*<\/div>\s*<\/div>/, `${tagInputMarkup}</div></div>`).replace(/<label class="uix-dropzone"[\s\S]*?<\/label>/, fileUploadMarkup);

forms.html = forms.html.replaceAll("<div  data-uix-richselect>", '<div class="uix-combobox" data-uix-richselect>');

// The Status field shows the real Select markup (HAR-1572): the docs-only rich select it replaces
// looked like a UIx list while every shipped Select opened the browser's own dropdown.
forms.html = forms.html.replace(/<label class="uix-field__label" id="status-sel-label">Status<\/label>\s*<div class="uix-combobox" data-uix-richselect>[\s\S]*?<\/ul>\s*<\/div>/, `<label class="uix-field__label" for="${SELECT_SPECIMENS.status.id}-form">Status</label>${selectMarkup({ ...SELECT_SPECIMENS.status, id: `${SELECT_SPECIMENS.status.id}-form` })}`);

forms.html = forms.html.replace(/<label class="uix-field__label" id="cat-sel-label">Category<\/label><div class="uix-combobox" data-uix-richselect>[\s\S]*?<\/ul><\/div>/, `<label class="uix-field__label" for="sel-category">Category</label>${selectMarkup({ id: 'sel-category', name: 'category', value: ['network'], items: [{ value: 'network', label: 'Network' }, { value: 'access', label: 'Access' }] })}`);

ADDITIONAL_EXAMPLES.push({
  module: "select",
  route: "examples-form-controls",
  title: "Select",
  html: selectStatesMarkup,
});

forms.html = forms.html.replace('id="rs-type" popover class="uix-cmdk"', 'id="rs-type" popover class="uix-popover uix-cmdk"');

const colorPicker = SHOWCASE_PAGES.find((page) => page.slug === "examples-color-picker");
colorPicker.html = colorPicker.html.replace(' aria-modal="true"', "").replace("normalized hex input, palettes, focus restoration", "normalized hex input, focus restoration");

colorPicker.html = colorPicker.html.replace('class="uix-color-picker__swatch uix-phase-page__brand-swatch"', 'class="uix-color-picker__swatch" style="background:var(--uix-accent)"').replace('class="uix-color-picker__preview uix-phase-page__brand-preview"', 'class="uix-color-picker__preview" style="background:var(--uix-accent);color:#fff"');

colorPicker.summary = colorPicker.summary.replace("normalized hex input, palettes, focus restoration", "normalized hex input, focus restoration");

// The gaps TENSOR found on 2.31.0 (HAR-1346 follow-ups, 2026-10-08). Each route's block is
// appended inside its closing </section>, after every earlier specimen, so the first match of
// each COMPONENT_SPECIMENS selector stays what it was.
for (const [slug, html] of Object.entries(TENSOR_GAP_SPECIMENS)) {
  const page = SHOWCASE_PAGES.find((entry) => entry.slug === slug);
  if (!page) throw new Error(`tensor-gap-specimens.js names a route that does not exist: ${slug}`);
  const end = page.html.lastIndexOf("</section>");
  if (end < 0) throw new Error(`${slug} has no closing </section> to append specimens to`);
  page.html = `${page.html.slice(0, end)}${html}\n${page.html.slice(end)}`;
}
